import json
import subprocess
import urllib.error
import urllib.request

repos = ["entirehq/entiredb", "entirehq/fleet", "entirehq/infra"]
branch = "codex/dual-write-checkpoints-v2-20260428"
title = "Dual write to checkpoints v1 and v2"
body = "This is a settings update to dual-write to checkpoints v1 and v2 as part of the checkpoints v2 migration plan. Please see the RFD in https://github.com/entirehq/company-knowledge/pull/51 for more details."

def git_token():
    proc = subprocess.run(
        ["/usr/bin/git", "credential", "fill"],
        input="protocol=https\nhost=github.com\n\n",
        text=True,
        capture_output=True,
        check=True,
    )
    for line in proc.stdout.splitlines():
        if line.startswith("password="):
            return line.removeprefix("password=")
    raise RuntimeError("no GitHub token from git credential helper")

token = git_token()

def gh(method, path, payload=None):
    data = None
    if payload is not None:
        data = json.dumps(payload).encode()
    req = urllib.request.Request("https://api.github.com" + path, data=data, method=method)
    req.add_header("Authorization", "Bearer " + token)
    req.add_header("Accept", "application/vnd.github+json")
    req.add_header("X-GitHub-Api-Version", "2022-11-28")
    if data is not None:
        req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            raw = resp.read()
            return json.loads(raw or b"{}")
    except urllib.error.HTTPError as e:
        raw = e.read().decode(errors="replace")
        raise RuntimeError(f"{method} {path} failed: HTTP {e.code}: {raw}") from e

results = []
for repo in repos:
    payload = {"title": title, "body": body, "head": branch, "base": "main", "draft": False}
    try:
        pr = gh("POST", f"/repos/{repo}/pulls", payload)
    except RuntimeError as err:
        # If a PR already exists for the branch, find and report it.
        existing = gh("GET", f"/repos/{repo}/pulls?head=entirehq:{branch}&state=open")
        if existing:
            pr = existing[0]
            status = "existing"
        else:
            raise err
    else:
        status = "created"
    results.append({"repo": repo, "status": status, "number": pr["number"], "url": pr["html_url"]})
    print(f"{repo}\t{status}\t#{pr['number']}\t{pr['html_url']}")

print("JSON " + json.dumps(results))
PY'

